"""Regression tests against fixtures generated by scripts/make_regression_fixtures.py.

The tolerance is loose enough to absorb floating-point reordering from
refactoring, and tight enough that any change to the science shows up.
"""

import json
from pathlib import Path

import numpy as np
import pytest
from regression_adapter import run_scenario

FIXTURE_DIR = Path(__file__).parent / "fixtures" / "regression"
FIXTURES = sorted(FIXTURE_DIR.glob("*.npz"))
RTOL = 1e-9
ATOL = 1e-9


def load(path: Path) -> tuple[dict, dict[str, np.ndarray], dict]:
    with np.load(path) as f:
        inputs = {
            k.removeprefix("input__"): f[k] for k in f.files if k.startswith("input__")
        }
        inputs["params"] = {
            k.removeprefix("param__"): float(f[k])
            for k in f.files
            if k.startswith("param__")
        }
        expected = {
            k.removeprefix("output__"): f[k]
            for k in f.files
            if k.startswith("output__")
        }
        meta = json.loads(str(f["meta"]))
    return inputs, expected, meta


def test_fixtures_exist():
    assert len(FIXTURES) >= 6


@pytest.mark.parametrize("path", FIXTURES, ids=lambda p: p.stem)
def test_regression(path):
    inputs, expected, _ = load(path)
    actual = run_scenario(inputs)
    for name, want in expected.items():
        np.testing.assert_allclose(
            actual[name], want, rtol=RTOL, atol=ATOL, err_msg=f"output {name!r}"
        )
